In C++, unqualified name lookup for an identifier 'id' occurs in the following order: local scope, then enclosing blocks, then namespace scopes via using directives. Example syntax with implementation notes:

namespace Outer {
    int var = 10;  // Declared in Outer namespace
    namespace Inner {
        void func();  // Declared in Inner namespace
    }  // Compiler adds this to the Inner scope in its symbol table
    using namespace Inner;  // Using directive makes Inner's declarations visible in Outer
}

int main() {
    int var = 20;  // Local scope declaration; shadows Outer::var
    func();  // Unqualified lookup: Compiler searches local scope first, then Outer (due to using directive), resolving to Outer::Inner::func
    return 0;
}
